import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'
import { urlToAction } from 'kea-router'

import { ApiRequest } from 'lib/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface exceptionIngestionLogicValues {
    hasSentExceptionEvent: boolean | null
    hasSentExceptionEventLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface exceptionIngestionLogicActions {
    loadExceptionIngestionState: () => any
    loadExceptionIngestionStateFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadExceptionIngestionStateSuccess: (
        hasSentExceptionEvent: boolean,
        payload?: any
    ) => {
        hasSentExceptionEvent: boolean
        payload?: any
    }
}

export type exceptionIngestionLogicType = MakeLogicType<exceptionIngestionLogicValues, exceptionIngestionLogicActions>

export const exceptionIngestionLogic = kea<exceptionIngestionLogicType>([
    path(['products', 'error_tracking', 'components', 'SetupPrompt', 'exceptionIngestionLogic']),
    loaders({
        hasSentExceptionEvent: {
            // `null` means "unknown" — not yet checked, or the check failed. Distinct from a
            // confirmed `false`, so callers can hide the banner while unknown rather than assert
            // "no events". Letting the request reject (no `.catch`) is what keeps a 403/500/503
            // as unknown instead of collapsing it into `false`.
            __default: null as boolean | null,
            loadExceptionIngestionState: async (): Promise<boolean> => {
                const response = await new ApiRequest().errorTrackingIssuesExists().get()
                return response.exists === true
            },
        },
    }),

    // A single afterMount fetch can't recover from a transient failure without a full page
    // reload. Re-attempt on every error tracking scene/tab activation, but only while the state
    // is still unknown — a resolved true/false is left untouched.
    urlToAction(({ actions, values }) => {
        const loadIfUnknown = (): void => {
            if (values.hasSentExceptionEvent === null && !values.hasSentExceptionEventLoading) {
                actions.loadExceptionIngestionState()
            }
        }
        return {
            '**/error_tracking': loadIfUnknown,
            '**/error_tracking/:id': loadIfUnknown,
            '**/error_tracking/:id/fingerprints': loadIfUnknown,
            '**/error_tracking/fingerprint/*': loadIfUnknown,
        }
    }),

    afterMount(({ actions, values }) => {
        if (values.hasSentExceptionEvent === null && !values.hasSentExceptionEventLoading) {
            actions.loadExceptionIngestionState()
        }
    }),
])
